def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_me, last_op = history[-1]
    if n == 1:
        return 'D' if last_op == 'D' else 'C'
    if n >= 99:
        return 'D'

    cntC = [0, 0, 0, 0]
    cntT = [0, 0, 0, 0]
    opp_c = 0
    after_C = 0
    after_C_c = 0
    after_D = 0
    after_D_c = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c += 1
        if i + 1 < n:
            no = history[i + 1][1]
            if m == 'C':
                after_C += 1
                if no == 'C':
                    after_C_c += 1
                st = 0 if o == 'C' else 1
            else:
                after_D += 1
                if no == 'C':
                    after_D_c += 1
                st = 2 if o == 'C' else 3
            cntT[st] += 1
            if no == 'C':
                cntC[st] += 1

    if opp_c == 0:
        return 'D'

    opp_rate = opp_c / float(n)
    if n >= 12 and opp_c * 10 <= n:
        return 'D'

    h = 100 - n
    if last_me == 'C' and last_op == 'C' and after_D == 0 and h > 3:
        if opp_rate >= 0.85:
            p = 0.09
        elif opp_rate >= 0.50:
            p = 0.06
        else:
            p = 0.02
        if rng.random() < p:
            return 'D'

    if after_C > 0:
        baseC = after_C_c / float(after_C)
    else:
        baseC = opp_rate
    if after_D >= 3:
        baseD = after_D_c / float(after_D)
    else:
        baseD = 0.0

    q = [0.0, 0.0, 0.0, 0.0]
    for st in range(4):
        if st < 2:
            p = (cntC[st] + baseC) / (cntT[st] + 1.0)
        else:
            p = (cntC[st] + 0.5 * baseD) / (cntT[st] + 0.5)
        if p < 0.0:
            p = 0.0
        elif p > 1.0:
            p = 1.0
        q[st] = p

    if h > 18:
        g = 0.95
        limit = 18
    else:
        g = 1.0
        limit = h - 1

    prev = [0.0, 0.0, 0.0, 0.0]
    for _ in range(limit):
        cur = [0.0, 0.0, 0.0, 0.0]
        for st in range(4):
            pc = q[st]
            pd = 1.0 - pc
            vc = pc * (3.0 + g * prev[0]) + pd * (g * prev[1])
            vd = pc * (5.0 + g * prev[2]) + pd * (1.0 + g * prev[3])
            if vc >= vd:
                cur[st] = vc
            else:
                cur[st] = vd
        prev = cur

    if last_me == 'C':
        state = 0 if last_op == 'C' else 1
    else:
        state = 2 if last_op == 'C' else 3

    pc = q[state]
    pd = 1.0 - pc
    valC = pc * (3.0 + g * prev[0]) + pd * (g * prev[1])
    valD = pc * (5.0 + g * prev[2]) + pd * (1.0 + g * prev[3])

    if valD > valC:
        return 'D'
    if valC > valD:
        return 'C'
    if rng.random() < 0.5:
        return 'D'
    return 'C'
